/** Strict captured cash plans, source facts, serial conservation and protected output linkage. */
public final class NpcCashSchema {
    private NpcCashSchema(){}
    public static List<String> statements(){var sql=new ArrayList<>(List.of(
        "CREATE TABLE npc_cash_adapter(singleton INTEGER PRIMARY KEY CHECK(singleton=1),world_id TEXT NOT NULL,operation_id TEXT NOT NULL,payload TEXT NOT NULL)",
        "CREATE TABLE npc_cash_quotes(id TEXT PRIMARY KEY,world_id TEXT NOT NULL,operation_id TEXT NOT NULL UNIQUE,financial_operation TEXT NOT NULL UNIQUE,input_custody TEXT NOT NULL UNIQUE,payload TEXT NOT NULL)",
        "CREATE TABLE npc_cash_returns(operation_id TEXT PRIMARY KEY,quote_id TEXT NOT NULL UNIQUE REFERENCES npc_cash_quotes(id),world_id TEXT NOT NULL,input_custody TEXT NOT NULL UNIQUE,return_custody TEXT NOT NULL UNIQUE,payload TEXT NOT NULL)",
        "CREATE TABLE npc_cash_receipts(operation_id TEXT PRIMARY KEY,quote_id TEXT NOT NULL UNIQUE REFERENCES npc_cash_quotes(id),world_id TEXT NOT NULL,effective_ms INTEGER NOT NULL CHECK(typeof(effective_ms)='integer' AND effective_ms>=0),fx_quote_id TEXT UNIQUE,input_custody TEXT NOT NULL UNIQUE,payload TEXT NOT NULL)",
        "CREATE INDEX npc_cash_fact_lookup ON journal_records(record_type,record_version,payload) WHERE record_type IN ('economy:a8/npc-cash-adapter','economy:a8/npc-cash-quote','economy:a8/npc-cash-trade','economy:a8/npc-cash-return')"));
        for(String table:List.of("npc_cash_adapter","npc_cash_quotes","npc_cash_receipts","npc_cash_returns")){for(String action:List.of("UPDATE","DELETE"))sql.add("CREATE TRIGGER "+table+"_"+action.toLowerCase(Locale.ROOT)+" BEFORE "+action+" ON "+table+" BEGIN SELECT RAISE(ABORT,'immutable NPC cash source'); END");String predicate=table.equals("npc_cash_adapter")?"singleton=NEW.singleton":table.equals("npc_cash_quotes")?"id=NEW.id OR operation_id=NEW.operation_id OR financial_operation=NEW.financial_operation OR input_custody=NEW.input_custody":"operation_id=NEW.operation_id OR quote_id=NEW.quote_id OR input_custody=NEW.input_custody";sql.add("CREATE TRIGGER "+table+"_replace BEFORE INSERT ON "+table+" WHEN EXISTS(SELECT 1 FROM "+table+" WHERE "+predicate+") BEGIN SELECT RAISE(ABORT,'existing NPC cash source'); END");}return List.copyOf(sql);}
    public static void validate(Connection c)throws SQLException{try{
        for(var expected:statements()){String name=expected.split(" ")[2].split("\\(",2)[0],actual=scalar(c,"SELECT sql FROM sqlite_master WHERE name=?",name);if(actual==null||!norm(actual).equals(norm(expected)))throw invalid("Cash schema: "+name);}String world=scalar(c,"SELECT world_id FROM foundation_metadata WHERE singleton=1");counts(c,"npc_cash_adapter",ADAPTER);counts(c,"npc_cash_quotes",QUOTE);counts(c,"npc_cash_receipts",RECEIPT);counts(c,"npc_cash_returns",RETURN);
        try(var s=c.createStatement();var rows=s.executeQuery("SELECT * FROM npc_cash_quotes")){while(rows.next()){var q=decodeQuote(rows.getString("payload"));if(!q.world().value().toString().equals(world)||!world.equals(rows.getString("world_id"))||!q.id().toString().equals(rows.getString("id"))||!q.terms().operation().toString().equals(rows.getString("financial_operation"))||!q.terms().inputCustody().toString().equals(rows.getString("input_custody"))||!stable("book|"+world+"|"+q.id()).toString().equals(rows.getString("operation_id")))throw invalid("Cash quote identity");long seq=fact(c,rows.getString("operation_id"),QUOTE,rows.getString("payload"));validateQuote(c,q,seq);}}
        long n=0;
        try(var s=c.createStatement();var rows=s.executeQuery("SELECT * FROM npc_cash_receipts")){while(rows.next()){n++;var r=decodeReceipt(rows.getString("payload"));String qPayload=scalar(c,"SELECT payload FROM npc_cash_quotes WHERE id=?",r.quote().toString());if(qPayload==null)throw invalid("Cash receipt quote");var q=decodeQuote(qPayload);if(!r.world().value().toString().equals(world)||!world.equals(rows.getString("world_id"))||!r.operation().toString().equals(rows.getString("operation_id"))||!r.quote().toString().equals(rows.getString("quote_id"))||!r.inputCustody().toString().equals(rows.getString("input_custody"))||r.effectiveMillis()!=rows.getLong("effective_ms")||!NpcCashTrades.receipt(q,r.effectiveMillis()).equals(r)||r.effectiveMillis()<q.issuedMillis()||r.effectiveMillis()>=q.expiresMillis())throw invalid("Cash receipt projection/terms");long seq=fact(c,r.operation().toString(),RECEIPT,rows.getString("payload"));
            String groups=scalar(c,"SELECT payload FROM journal_records WHERE sequence=? AND record_type=? AND record_version=1",Long.toString(seq),NpcSettlement.GROUPS);if(groups==null||!"1".equals(scalar(c,"SELECT COUNT(*) FROM journal_records WHERE sequence=? AND record_type=?",Long.toString(seq),NpcSettlement.GROUPS))||!NpcSettlement.decode(groups).world().equals(q.world())||!NpcSettlement.decode(groups).groups().equals(NpcCashTrades.expectedGroups(q)))throw invalid("Cash financial groups differ from exact plan");
            if(!"0".equals(scalar(c,"SELECT COUNT(*) FROM journal_records WHERE sequence=? AND record_type=?",Long.toString(seq),FxSettlement.FACT)))throw invalid("Duplicate cash FX source");if(!Objects.equals(rows.getString("fx_quote_id"),q.fx()==null?null:q.fx().conversion().id().toString()))throw invalid("Cash FX consumption owner");if(q.fx()!=null){if(!"1".equals(scalar(c,"SELECT COUNT(*) FROM ledger_fx_quotes WHERE quote_id=?",q.fx().conversion().id().toString())))throw invalid("Cash FX not consumed");var f=ServicePricing.fact(q.fx().pricing());if(!"1".equals(scalar(c,"SELECT COUNT(*) FROM journal_records WHERE sequence=? AND record_type=? AND record_version=? AND payload=?",Long.toString(seq),f.type(),Integer.toString(f.version()),f.payload())))throw invalid("Cash fee supplier fact");}
            String stock=scalar(c,"SELECT payload FROM trade_stock_events WHERE operation_id=? AND sequence=?",r.operation().toString(),Long.toString(seq)),price=scalar(c,"SELECT payload FROM trade_market_events WHERE operation_id=? AND sequence=?",r.operation().toString(),Long.toString(seq));if(stock==null||price==null||StockFacts.decode(stock).action()!=StockFacts.Action.TRADE||!StockFacts.decode(stock).progression().originalOperation().equals(r.operation())||!MarketFacts.decode(price).price().demand().equals(q.pricing().price().nextDemand())||!MarketFacts.decode(price).carry().pricing().equals(q.pricing().price().nextCarry()))throw invalid("Cash atomic price/stock/progression");
            custody(c,q,q.terms().inputCustody(),q.terms().exactInputItems(),NpcCashTrades.inputSource(q.terms()),NpcCashTrades.inputDestination(q.terms()),true);
            if(q.terms().outputCustody()!=null){var offer=offer(c,q);custody(c,q,q.terms().outputCustody(),ca.emilybelnavis.mcmods.economy.trade.settlement.NpcTrades.outputItems(offer,q.terms().executions()),NpcCashTrades.outputSource(q.terms()),NpcCashTrades.outputDestination(q.terms()),false);}
            if(!q.outputLots().isEmpty())custody(c,q,q.terms().cashCustody(),WithdrawalDelivery.items(q.outputLots()),"npc-cash:"+q.terms().trader(),"player:"+q.terms().actor().value(),false);
            for(var lot:q.inputLots()){int used=NpcCashTrades.markedQuantities(q.terms().cash()).get(lot.id());String p=cashFact(CashIssuance.Action.REDEEM,new CashIssuance.Lot(lot.world(),lot.id(),lot.item(),lot.issued(),lot.remaining()-used,lot.state(),lot.revision()+1,"npc-custody:"+q.terms().inputCustody()));if(!"1".equals(scalar(c,"SELECT COUNT(*) FROM journal_records WHERE sequence=? AND record_type=? AND payload=?",Long.toString(seq),CashIssuance.FACT,p)))throw invalid("Original marked cash redemption fact");if(!"RELEASED".equals(scalar(c,"SELECT state FROM custody_cash_reservations WHERE custody_id=? AND lot_id=?",q.terms().inputCustody().toString(),lot.id().toString())))throw invalid("Consumed cash lock not released");}
            for(var lot:q.outputLots()){if(!"1".equals(scalar(c,"SELECT COUNT(*) FROM journal_records WHERE sequence=? AND record_type=? AND payload=?",Long.toString(seq),CashIssuance.FACT,cashFact(CashIssuance.Action.ISSUE,lot))))throw invalid("Original cash payout lot fact");String count=scalar(c,"SELECT count FROM custody_cash_reservations WHERE custody_id=? AND lot_id=?",q.terms().cashCustody().toString(),lot.id().toString());if(count==null||Integer.parseInt(count)!=lot.issued())throw invalid("Cash payout protection missing");}
        }}
        try(var statement=c.createStatement();var returns=statement.executeQuery("SELECT * FROM npc_cash_returns")){while(returns.next()){var r=decodeReturn(returns.getString("payload"));if(!r.world().value().toString().equals(world)||!r.operation().toString().equals(returns.getString("operation_id"))||!r.quote().toString().equals(returns.getString("quote_id"))||!r.inputCustody().toString().equals(returns.getString("input_custody"))||!r.returnCustody().toString().equals(returns.getString("return_custody"))||!"DURABLY_REJECTED".equals(scalar(c,"SELECT status FROM operation_outcomes WHERE world_id=? AND operation_id=?",world,r.original().toString())))throw invalid("Cash return original outcome");fact(c,r.operation().toString(),RETURN,returns.getString("payload"));
            String quotePayload=scalar(c,"SELECT payload FROM npc_cash_quotes WHERE id=?",r.quote().toString());if(quotePayload==null)throw invalid("Return quoted source missing");var q=decodeQuote(quotePayload);
            if(!q.terms().operation().equals(r.original())||!q.terms().inputCustody().equals(r.inputCustody())||!stable("return|"+world+"|"+r.original()).equals(r.operation())||!stable("return-custody|"+world+"|"+r.original()).equals(r.returnCustody())||!r.evidence().location().equals(NpcCashTrades.inputSource(q.terms())))throw invalid("Return canonical source identity");
            for(UUID id:List.of(r.inputCustody(),r.returnCustody()))if(!q.terms().exactInputItems().equals(scalar(c,"SELECT items FROM custody_cases WHERE id=?",id.toString()))||!("player:"+q.terms().actor().value()).equals(scalar(c,"SELECT owner FROM custody_cases WHERE id=?",id.toString()))||!NpcCashTrades.inputSource(q.terms()).equals(scalar(c,"SELECT source FROM custody_cases WHERE id=?",id.toString())))throw invalid("Return exact originals/owner/source");
            if(!NpcCashTrades.inputSource(q.terms()).equals(scalar(c,"SELECT destination FROM custody_cases WHERE id=?",r.returnCustody().toString())))throw invalid("Return original destination");
            for(var lock:NpcCashTrades.markedQuantities(q.terms().cash()).entrySet()){String sourceState=scalar(c,"SELECT state FROM custody_cash_reservations WHERE custody_id=? AND lot_id=?",r.inputCustody().toString(),lock.getKey().toString());if(!(r.knownHeld()?"RELEASED":"ACTIVE").equals(sourceState))throw invalid("Return input cash protection");if(r.knownHeld()){String count=scalar(c,"SELECT count FROM custody_cash_reservations WHERE custody_id=? AND lot_id=?",r.returnCustody().toString(),lock.getKey().toString());if(count==null||Integer.parseInt(count)!=lock.getValue())throw invalid("Return transferred original quantity");String state=scalar(c,"SELECT state FROM custody_cash_reservations WHERE custody_id=? AND lot_id=?",r.returnCustody().toString(),lock.getKey().toString());String custodyState=scalar(c,"SELECT state FROM custody_cases WHERE id=?",r.returnCustody().toString());if(!state.equals(custodyState.equals("DELIVERED")||custodyState.equals("COMPENSATED")?"RELEASED":"ACTIVE"))throw invalid("Return output protection lifetime");}}
            if(!"QUARANTINED".equals(scalar(c,"SELECT state FROM custody_cases WHERE id=?",r.inputCustody().toString()))||scalar(c,"SELECT financial_operation FROM custody_cases WHERE id=?",r.inputCustody().toString())!=null||!r.inputCustody().toString().equals(scalar(c,"SELECT reservation_operation FROM custody_cases WHERE id=?",r.returnCustody().toString()))||!r.operation().toString().equals(scalar(c,"SELECT financial_operation FROM custody_cases WHERE id=?",r.returnCustody().toString())))throw invalid("Cash return custody source");}}
        String adapter=scalar(c,"SELECT payload FROM npc_cash_adapter WHERE singleton=1");if((n==0)!=(adapter==null))throw invalid("Cash adapter installation");if(adapter!=null){var a=decodeAdapter(adapter);String op=scalar(c,"SELECT operation_id FROM npc_cash_adapter WHERE singleton=1");if(!a.world().value().toString().equals(world)||scalar(c,"SELECT operation_id FROM npc_cash_receipts WHERE operation_id=?",op)==null)throw invalid("Cash adapter owner");long seq=fact(c,op,ADAPTER,adapter);if(seq!=Long.parseLong(scalar(c,"SELECT MIN(t.sequence) FROM npc_cash_receipts r JOIN journal_transactions t ON t.operation_id=r.operation_id")))throw invalid("Cash adapter chronology");}
    }catch(RuntimeException bad){throw new SQLException("Invalid NPC cash source",bad);}}
    private static void validateQuote(Connection c,Quote q,long seq)throws SQLException{if(!q.financialIntent().equals(NpcCashTrades.financialIntent(q.world(),q.terms().operation(),q.terms().actor())))throw invalid("Cash original intent");var p=q.pricing();var result=ca.emilybelnavis.mcmods.economy.trade.pricing.Pricing.quote(p.request());if(!result.available()||!result.quote().equals(p.price()))throw invalid("Cash pricing snapshot");var offer=offer(c,q);if(!offer.goods().priceKey().equals(p.request().key().item())||offer.side()!=p.request().key().side()||p.request().goods()!=Math.multiplyExact((long)offer.goodsCount(),q.terms().executions()))throw invalid("Cash offer snapshot");
        if(p.request().standardQuantity()!=offer.standardQuantity()||!p.request().reputation().equals(q.terms().reputation())||!p.request().comparisons().equals(q.terms().comparisons())||!p.request().key().actor().equals(q.terms().actor().value())||!p.request().key().epoch().equals(q.terms().epoch()))throw invalid("Cash frozen pricing inputs");
        var raw=q.terms().source().basis(offer.emeraldCount(),offer.goodsCount(),offer.standardQuantity());boolean basis=false;for(var comparison:q.terms().comparisons())try{if(Pricing.normalizedBasis(offer.side(),raw,comparison).equals(p.request().basis()))basis=true;}catch(IllegalArgumentException other){}if(!basis)throw invalid("Cash original source basis");
        // Startup validation streams immutable legacy publications; interaction paths use indexed live reads.
        FxFacts.Publication publication=null;
        try(var query=c.prepareStatement("SELECT payload,record_version FROM journal_records WHERE record_type=? AND sequence<? ORDER BY sequence DESC")){query.setString(1,FxFacts.PUBLICATION);query.setLong(2,seq);try(var rows=query.executeQuery()){while(rows.next()){var candidate=FxFacts.Publication.decode(rows.getString(1),rows.getInt(2));publication=candidate;break;}}}
        if(publication==null||!publication.updateId().equals(q.terms().source().fxSnapshot())||q.terms().source().marketCurrency()!=p.request().basis().currency()||!q.terms().source().cadPerMarketMajor().equals(Rational.of(publication.rates().get(p.request().basis().currency())).divide(Rational.of(publication.rates().get(EconomyCurrency.CAD)))))throw invalid("Cash historical FX source");
        long sourceEffective=publication.day().atStartOfDay(java.time.ZoneOffset.UTC).toInstant().toEpochMilli();
        if(q.issuedMillis()<sourceEffective||q.expiresMillis()>sourceEffective+172800000L)throw invalid("Cash historical source freshness");
        String priorPrice=scalar(c,"SELECT payload FROM trade_market_events WHERE price_market=? AND price_item=? AND sequence<? ORDER BY sequence DESC LIMIT 1",p.market().toString(),p.request().key().item(),Long.toString(seq));if(p.priceRevision()!=(priorPrice==null?0:MarketFacts.decode(priorPrice).price().revision())||!p.request().demand().equals(priorPrice==null?new Pricing.Demand(Rational.ZERO,0):MarketFacts.decode(priorPrice).price().demand()))throw invalid("Cash historical demand");
        String carryKey=MarketFacts.stable(String.join("|",p.market().toString(),p.request().key().item(),q.terms().actor().value().toString(),p.request().key().side().name(),q.terms().epoch().toString())).toString();String carry=scalar(c,"SELECT payload FROM trade_market_events WHERE carry_key=? AND sequence<? ORDER BY sequence DESC LIMIT 1",carryKey,Long.toString(seq));if(!p.request().carry().equals(carry==null?Pricing.Carry.empty(p.request().key()):MarketFacts.decode(carry).carry().pricing()))throw invalid("Cash historical carry");
        String tick=scalar(c,"SELECT payload FROM trade_stock_events WHERE market_id=? AND sequence<? ORDER BY sequence DESC LIMIT 1",p.market().toString(),Long.toString(seq));if(p.marketTickRevision()!=(tick==null?0:StockFacts.decode(tick).market().revision())||p.eligibleTick()!=(tick==null?0:StockFacts.decode(tick).market().eligibleTicks())||p.request().eligibleTick()!=p.eligibleTick())throw invalid("Cash historical market clock");
        if(q.fx()!=null){var f=q.fx();boolean buySide=offer.side()==Pricing.Side.BUY;var from=buySide?q.terms().cashCurrency():p.request().basis().currency();var to=buySide?p.request().basis().currency():q.terms().cashCurrency();
            if(!f.supplier().equals(q.supplier())||f.side()!=offer.side()||f.goodsGross().currency()!=p.request().basis().currency()||f.goodsGross().minorUnits()!=p.price().minor()||!f.conversion().actor().equals(q.terms().actor())||!f.conversion().world().equals(q.world())||!f.conversion().publication().equals(publication.updateId())||f.conversion().pair().source()!=from||f.conversion().pair().target()!=to||f.conversion().side()!=(buySide?FxQuotes.Side.EXACT_CREDIT:FxQuotes.Side.EXACT_DEBIT)||f.pricing().service()!=ServicePricing.Service.NPC_CASH_FX||!f.pricing().institution().equals(q.supplier())||!f.pricing().owner().equals(q.terms().actor())||!f.pricing().world().equals(q.world())||!f.pricing().fee().equals(ServicePricing.fee(f.pricing().principal(),ServicePricing.Service.NPC_CASH_FX,f.pricing().tier())))throw invalid("Cash captured FX supplier/policy");
            var original=f.conversion();
            var replay=new FxQuotes(q.world()).issue(q.terms().actor(),original.pair(),original.side(),original.requested(),publication,f.issuedAt(),java.time.Duration.between(f.issuedAt(),original.expires()));
            if(!original.debit().equals(replay.debit())||!original.credit().equals(replay.credit())||!original.fee().equals(replay.fee())||original.pricing()!=null||original.pricingVersion()!=1||f.issuedAt().toEpochMilli()!=q.issuedMillis()||f.expiresAt().toEpochMilli()!=q.expiresMillis()||original.expires().isBefore(f.expiresAt())||f.pricing().expires().isBefore(f.expiresAt()))throw invalid("Cash FX historical rate arithmetic/lifetime");
            if(buySide?f.conversion().credit().minorUnits()!=p.price().minor()||!f.pricing().principal().equals(f.conversion().debit()):f.pricing().principal().minorUnits()!=p.price().minor()||f.conversion().debit().minorUnits()!=p.price().minor()-f.pricing().fee().minorUnits())throw invalid("Cash actual FX principal/gross fee");
        }else if(q.terms().cashCurrency()!=p.request().basis().currency())throw invalid("Implicit cash FX");
        long total=0,unmarked=0;for(var slot:q.terms().cash()){var d=CashDenominations.require(slot.claim().item());if(d.currency()!=q.terms().cashCurrency()||!slot.claim().world().equals(q.world()))throw invalid("Cash original denomination/world");long value=Math.multiplyExact(d.minorUnits(),slot.claim().count());total=Math.addExact(total,value);if(slot.unmarked())unmarked=Math.addExact(unmarked,value);}if(total!=q.inputCashMinor()||unmarked!=q.operatorCashMinor())throw invalid("Cash face-value provenance");var marked=NpcCashTrades.markedQuantities(q.terms().cash());if(marked.size()!=q.inputLots().size())throw invalid("Cash original lot manifest");for(var lot:q.inputLots()){if(!marked.containsKey(lot.id())||lot.state()!=CashIssuance.State.ACTIVE||lot.remaining()<marked.get(lot.id())||!lot.world().equals(q.world()))throw invalid("Cash original lot quantity");String count=scalar(c,"SELECT count FROM custody_cash_reservations WHERE custody_id=? AND lot_id=?",q.terms().inputCustody().toString(),lot.id().toString());if(count==null||Integer.parseInt(count)!=marked.get(lot.id()))throw invalid("Cash booked original lock");}
        boolean buy=offer.side()==ca.emilybelnavis.mcmods.economy.trade.pricing.Pricing.Side.BUY;long required=buy?(q.fx()==null?p.price().minor():Math.addExact(q.fx().conversion().debit().minorUnits(),q.fx().pricing().fee().minorUnits())):0,output=buy?total-required:q.fx()==null?p.price().minor():q.fx().conversion().credit().minorUnits();if(required!=q.requiredCashMinor()||output!=q.cashOutputMinor()||output<0)throw invalid("Cash exact change/payout");if(q.plan()!=null){for(var line:q.plan().lines())if(!CashDenominations.require(line.denomination().id()).equals(line.denomination()))throw invalid("Arbitrary cash denomination");if(!NpcCashTrades.lots(q.world(),q.terms().operation(),q.plan()).equals(q.outputLots()))throw invalid("Original cash lot identity");}
        String binding=scalar(c,"SELECT payload FROM trade_market_events WHERE binding_trader=? AND sequence<? ORDER BY sequence DESC LIMIT 1",q.terms().trader().toString(),Long.toString(seq)),stock=scalar(c,"SELECT payload FROM trade_stock_events WHERE trader_id=? AND sequence<? ORDER BY sequence DESC LIMIT 1",q.terms().trader().toString(),Long.toString(seq));if(binding==null||stock==null||!MarketFacts.decode(binding).binding().market().equals(p.market())||MarketFacts.decode(binding).binding().revision()!=p.bindingRevision()||StockFacts.decode(stock).trader().revision()!=p.stockRevision())throw invalid("Cash captured binding/stock");
    }
    private static TradeCatalog.Offer offer(Connection c,Quote q)throws SQLException{String p=scalar(c,"SELECT payload FROM trade_catalog_offers WHERE trader_id=? AND revision=? AND ordinal=?",q.terms().trader().toString(),Long.toString(q.terms().catalogRevision()),Integer.toString(q.terms().offerOrdinal()));if(p==null)throw invalid("Missing cash catalog");return CatalogFacts.decodeEntry(p).offer();}
    private static void custody(Connection c,Quote q,UUID id,String items,String source,String destination,boolean witnessed)throws SQLException{if(!q.terms().operation().toString().equals(scalar(c,"SELECT financial_operation FROM custody_cases WHERE id=?",id.toString()))||!q.financialIntent().equals(scalar(c,"SELECT financial_intent FROM custody_cases WHERE id=?",id.toString()))||!items.equals(scalar(c,"SELECT items FROM custody_cases WHERE id=?",id.toString()))||!("player:"+q.terms().actor().value()).equals(scalar(c,"SELECT owner FROM custody_cases WHERE id=?",id.toString()))||!source.equals(scalar(c,"SELECT source FROM custody_cases WHERE id=?",id.toString()))||!destination.equals(scalar(c,"SELECT destination FROM custody_cases WHERE id=?",id.toString()))||witnessed&&scalar(c,"SELECT reservation_witness FROM custody_cases WHERE id=?",id.toString())==null)throw invalid("Cash exact custody/save linkage");}
    private static String cashFact(CashIssuance.Action a,CashIssuance.Lot l){return a+"|"+l.world().value()+"|"+l.id()+"|"+l.item()+"|"+l.issued()+"|"+l.remaining()+"|"+l.state()+"|"+l.revision()+"|"+Base64.getUrlEncoder().withoutPadding().encodeToString(l.evidence().getBytes(java.nio.charset.StandardCharsets.UTF_8));}
    private static void counts(Connection c,String table,String type)throws SQLException{if(!scalar(c,"SELECT COUNT(*) FROM "+table).equals(scalar(c,"SELECT COUNT(*) FROM journal_records WHERE record_type=?",type)))throw invalid("Cash fact/projection count");}
    private static long fact(Connection c,String op,String type,String payload)throws SQLException{String seq=scalar(c,"SELECT t.sequence FROM journal_transactions t JOIN journal_records r ON r.sequence=t.sequence WHERE t.operation_id=? AND r.record_type=? AND r.record_version=1 AND r.payload=?",op,type,payload);if(seq==null||!"1".equals(scalar(c,"SELECT COUNT(*) FROM journal_transactions t JOIN journal_records r ON r.sequence=t.sequence WHERE t.operation_id=? AND r.record_type=? AND r.record_version=1 AND r.payload=?",op,type,payload)))throw invalid("Cash immutable journal linkage");return Long.parseLong(seq);}
    private static String scalar(Connection c,String sql,String...params)throws SQLException{try(var s=c.prepareStatement(sql)){for(int i=0;i<params.length;i++)s.setString(i+1,params[i]);try(var r=s.executeQuery()){return r.next()?r.getString(1):null;}}}
    private static String norm(String s){return s.replaceAll("\\s+"," ").trim();}private static SQLException invalid(String s){return new SQLException(s);}
}
